package com.hoc.balancedflight;

import com.hoc.balancedflight.BalancedFlight;
import com.hoc.balancedflight.content.flightAnchor.FlightAnchorPonderScene;
import com.tterrag.registrate.util.entry.ItemProviderEntry;
import com.tterrag.registrate.util.entry.RegistryEntry;
import net.createmod.ponder.api.registration.PonderSceneRegistrationHelper;
import net.createmod.ponder.api.registration.PonderTagRegistrationHelper;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.level.ItemLike;

public class AllPonderScenes {
    public static final ResourceLocation FLIGHT_ANCHOR = ResourceLocation.fromNamespaceAndPath((String)"balancedflight", (String)"flight_anchor");

    public static void registerTags(PonderTagRegistrationHelper<ResourceLocation> helper) {
        PonderTagRegistrationHelper tagHelper = helper.withKeyFunction(RegistryEntry::getId);
        tagHelper.registerTag(FLIGHT_ANCHOR).addToIndex().item((ItemLike)BalancedFlight.FLIGHT_ANCHOR_BLOCK.get()).title("Flight Anchor").description("Powered flight with Rotational Force").register();
        tagHelper.addToTag(FLIGHT_ANCHOR).add(BalancedFlight.FLIGHT_ANCHOR_BLOCK);
    }

    public static void registerScenes(PonderSceneRegistrationHelper<ResourceLocation> helper) {
        PonderSceneRegistrationHelper sceneHelper = helper.withKeyFunction(RegistryEntry::getId);
        sceneHelper.forComponents((Object[])new ItemProviderEntry[]{BalancedFlight.FLIGHT_ANCHOR_BLOCK}).addStoryBoard("flight_anchor", FlightAnchorPonderScene::ponderScene, new ResourceLocation[]{FLIGHT_ANCHOR});
    }
}

