    public static final BlockEntry<? extends Block> FLIGHT_ANCHOR_BLOCK = ((BlockBuilder)RegistrateExtensions.geckoItem(((CreateRegistrate)CREATE_REGISTRATE.object("flight_anchor")).block(FlightAnchorBlock::new).properties(properties -> BlockBehaviour.Properties.m_284310_().m_284180_(MapColor.f_283906_).m_60978_(10.0f).m_60918_(SoundType.f_56725_).m_60955_()).defaultLoot().tag(new TagKey[]{BlockTags.f_144282_}).tag(new TagKey[]{BlockTags.f_144285_}), FlightAnchorItem::new).initialProperties(() -> new Item.Properties().m_41487_(1)).build()).register();
    public static final BlockEntityEntry<FlightAnchorEntity> FLIGHT_ANCHOR_BLOCK_ENTITY = CREATE_REGISTRATE.blockEntity("flight_anchor", FlightAnchorEntity::new).visual(() -> FlightAnchorKineticInstance::new).validBlock(FLIGHT_ANCHOR_BLOCK).renderer(() -> AllGeckoRenderers.FlightAnchorGeckoRenderer.TileRenderer::apply).register();
    public static final ItemEntry<? extends Item> ASCENDED_FLIGHT_RING = CREATE_REGISTRATE.item("ascended_flight_ring", FlightRing::new).initialProperties(() -> new Item.Properties().m_41487_(1)).register();

    public BalancedFlight() {
        IEventBus modEventBus = FMLJavaModLoadingContext.get().getModEventBus();
        IEventBus forgeEventBus = MinecraftForge.EVENT_BUS;
        CREATE_REGISTRATE.registerEventListeners(modEventBus);
        BalancedFlightConfig.init();
        MinecraftForge.EVENT_BUS.register((Object)this);
        AllLangMessages.init();
        AllCreativeTabs.register(modEventBus);
        modEventBus.addListener(EventPriority.LOWEST, BalancedFlight::gatherData);
        DistExecutor.unsafeRunWhenOn((Dist)Dist.CLIENT, () -> () -> BalancedFlightClient.onCtorClient(modEventBus, forgeEventBus));
    }

    public static void gatherData(GatherDataEvent event) {
        CREATE_REGISTRATE.addDataGenerator(ProviderType.LANG, prov -> {
            prov.add((CreativeModeTab)AllCreativeTabs.CREATIVE_TAB.get(), "Create: Balanced Flight");
            prov.add("curios.identifier.flight_ring", "Flight Ring");
        });
        DataGenerator gen = event.getGenerator();
        PackOutput output = gen.getPackOutput();
        if (event.includeServer()) {
            gen.addProvider(true, (DataProvider)new BalancedFlightRecipeGen(output));
        }
    }

    static {
        CREATE_REGISTRATE.setCreativeTab(AllCreativeModeTabs.BASE_CREATIVE_TAB);
        CREATE_REGISTRATE.setTooltipModifierFactory(item -> new ItemDescription.Modifier(item, FontHelper.Palette.STANDARD_CREATE).andThen(TooltipModifier.mapNull((TooltipModifier)KineticStats.create((Item)item))));

