public void setActive(boolean active) {
    Level level = this.getWorld();
    BlockPos pos = this.getPos();
    if (level instanceof PonderLevel) {
        return;
    }
    if (!active) {
        FlightAnchorEntity.ActiveAnchors.remove(pos);
        FlightAnchorBehaviour.playSound(level, pos, SoundEvents.f_11738_);
        return;
    }
    if (!FlightAnchorEntity.ActiveAnchors.containsKey(pos)) {
        FlightAnchorEntity.ActiveAnchors.put(pos, (FlightAnchorEntity)this.blockEntity);
        FlightAnchorBehaviour.playSound(level, pos, SoundEvents.f_11736_);
    }
}

public void initialize() {
    if (this.getWorld().f_46443_) {
        ((FlightAnchorEntity)this.blockEntity).placedRenderTime = AnimationTickHolder.getRenderTime((LevelAccessor)this.getWorld());
    }
}

public void unload() {
    this.setActive(false);
}

public void tick() {
    super.tick();
    FlightAnchorEntity anchor = (FlightAnchorEntity)this.blockEntity;
    boolean previouslyActive = anchor.isActive;
    anchor.isActive = anchor.isSpeedRequirementFulfilled();
    if (anchor.isActive && !previouslyActive) {
        this.setActive(true);
    } else if (!anchor.isActive && previouslyActive) {
        this.setActive(false);
        anchor.beamSections.clear();
        anchor.checkingBeamSections.clear();
    }
    if (anchor.isActive) {
        FlightAnchorBehaviour.beaconTick(this.getWorld(), this.getPos(), anchor);
    }
