        float stress;
        this.lastStressApplied = stress = (float)((Integer)BalancedFlightConfig.anchorStress.get()).intValue();
        return stress;
    }

    public List<BeaconBlockEntity.BeaconBeamSection> getBeamSections() {
        return this.beamSections;
    }
}

